# -*- coding: utf-8 -*-
"""Verilog course chapters 11-14: testbenches, finite state machines, hierarchy and memories, RTL to silicon and the capstone CPU."""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "cd"))
from clib import *  # noqa: F401,F403


def F(name, cap): return {"type": "figure", "image": name, "caption": cap}
def TB(title, head, rows): return {"type": "table", "title": title, "head": head, "rows": rows}
def V(code): return C(code, "verilog")
CHS = []

CHS.append(CH(
 "Testbenches: how to know your design works",
 ("Testbenches", []),
 ["A design you have not tested is a design that does not work. A testbench is a Verilog module with no ports that creates a clock, applies inputs, watches the outputs and says pass or fail.",
  "You will learn the structure of a testbench, the system tasks that print and record, how to loop over all inputs, how to use random numbers against a reference, and why a test must be able to fail.",
  "Good habits here are worth more than any other skill in this course: professional chip teams spend more time on verification than on design."],
 [("Testbench", "A module that wraps the design under test (DUT) and supplies its stimulus."),
  ("DUT", "Design under test."),
  ("Stimulus", "The input values and clocks a testbench applies."),
  ("Self-checking", "A testbench that compares outputs to expected values and prints pass or fail by itself."),
  ("Reference model", "A simple, obviously correct description of what the DUT should compute."),
  ("Waveform (VCD)", "A recording of signals over time that a viewer can display."),
  ("Task", "A reusable block of testbench code, called like a procedure.")],
 ["A testbench has no ports: reg for inputs, wire for outputs, an instance of the DUT, and an initial block.",
  "Generate a clock with always #5 clk = ~clk;",
  "Use display and monitor tasks to print, dumpfile and dumpvars to record a waveform, finish to stop.",
  "Self-checking tests compare to a reference and count errors.",
  "A test that cannot fail proves nothing: include corner cases and boundaries."],
 [T("Imagine you have built a coffee machine. You would not hand it to customers without pressing buttons and tasting the result. A testbench is that for a circuit. It is a module with no ports, because it is the whole world around the design. Inside it you place the design under test, give it a clock, drive its inputs, and look at what comes out. (See Figure 11.1 below.)"),
  F("vl-tbarch.svg", "A self-checking testbench. A stimulus generator drives the design and a reference model; a checker compares and reports."),
  V("module tb;\n  reg  a, b, cin;            // inputs: reg, because we drive them\n  wire sum, cout;            // outputs: wire, because the DUT drives them\n  full_adder dut(.a(a), .b(b), .cin(cin), .sum(sum), .cout(cout));\n  initial begin\n    $dumpfile(\"dump.vcd\");   // record a waveform\n    $dumpvars(0, tb);\n    {a, b, cin} = 3'b000; #10;\n    {a, b, cin} = 3'b011; #10;\n    $display(\"sum=%b cout=%b\", sum, cout);\n    $finish;                 // end the simulation\n  end\nendmodule"),
  T("Read the structure. Inputs are regs because the testbench drives them from procedural code. Outputs are wires because the DUT drives them. The DUT is instantiated by name. The initial block runs once: it starts the waveform recording, sets inputs, waits with the hash delay, prints, and ends. Without a finish task a clock-driven simulation would run forever."),
  TB("Testbench system tasks", ["Task", "Does", "Example use"], [["dollar-display", "print once, like printf", "show a value at one moment"], ["dollar-monitor", "print every time any listed signal changes", "trace a whole run"], ["dollar-time", "current simulation time", "stamp a message"], ["dollar-finish", "end the simulation", "last line of the test"], ["dollar-dumpfile / dollar-dumpvars", "record every signal into a waveform file", "view in a waveform viewer"], ["dollar-random", "a random 32-bit number", "random stimulus"]]),
  T("Sequential designs need a clock. A clock is a signal that flips every half period. The standard recipe is two lines: reg clk = 0; always #5 clk = ~clk;. The always block with only a delay repeats forever, inverting clk every 5 time units, so the period is 10 units. With a timescale of 1 ns that is a 100 MHz clock. (See Figure 11.2 below.)"),
  F("vl-clkgen.svg", "A clock generated with always #5 clk = ~clk. Rising edges occur at 5, 15 and 25."),
  T("How many inputs should you test? For a full adder there are only 3 input bits: eight cases. Test them all with a loop. A for loop in a testbench is real code that runs over time: put the loop counter on the inputs, wait a moment, and compare the outputs to what Verilog's own plus operator gives. This is exhaustive testing, and it is the best kind when it is affordable."),
  V("integer i, errs;\ninitial begin\n  errs = 0;\n  for (i = 0; i < 8; i = i + 1) begin\n    {a, b, cin} = i[2:0];\n    #5;\n    if ({cout, sum} !== a + b + cin) begin\n      errs = errs + 1;\n      $display(\"FAIL a=%b b=%b cin=%b\", a, b, cin);\n    end\n  end\n  if (errs == 0) $display(\"ALL PASS\");\n  $finish;\nend"),
  T("Notice the !== operator. It compares exactly, including x and z, and gives a plain 0 or 1. If the DUT's output were x, an ordinary comparison would give x, and the if would quietly treat it as false, hiding the error. Use the case equality operators in testbenches. The expression a + b + cin on the right is the reference model: a simple trusted calculation of the answer."),
  T("When the inputs are too many to try all of them, use random tests. dollar-random gives a random number each time. Apply a few hundred or thousand random input pairs, check each against the reference, and count the failures. Random testing finds surprising bugs, but add a few directed tests too: zero, the maximum value and, above all, boundaries."),
  TB("Testing strategies", ["Strategy", "How", "Best when"], [["directed", "you pick interesting cases by hand", "the corner cases are known"], ["exhaustive", "loop over every input combination", "fewer than about 20 input bits"], ["random", "dollar-random with a reference model", "many inputs"], ["self-checking", "compare automatically, print pass or fail", "always; do not rely on staring at waveforms"]]),
  T("A test that cannot fail proves nothing. Imagine a comparator that wrongly says a is greater than b when they are equal. A test that only tries a = 1, b = 2 and a = 3, b = 1 passes. Only a = b exposes the bug. This is why testers always try boundaries: equal values, zero, maximum, wrap-around. The third lab level hands you a buggy design and a weak testbench, and asks you to add the vectors that make it fail."),
  TB("Typical testbench mistakes", ["Mistake", "Effect", "Remedy"], [["no finish task", "a clocked simulation never ends", "always end with the finish task"], ["comparing with == when x is possible", "x hides errors", "use !== in checks"], ["inputs declared wire", "cannot assign them in initial", "declare inputs as reg"], ["testing only the happy path", "bugs at the boundaries survive", "add corner cases"], ["reading outputs at the same instant as inputs change", "sees old values", "wait a few time units first"]]),
  T("Finally, look at the waveform. Self-checking tests tell you whether something is wrong. The waveform tells you why. Zoom in around the failure and trace backwards through the signals. The labs include a small waveform viewer under the console for exactly this reason. A good habit: when a test fails, read the first failure, not the last, since later ones are often consequences of it."),
  T("The lab for this chapter turns the tables: the circuit is given and you write the testbench. You build a clock, an exhaustive loop, a bug-catching test and a random test, and then give an inverter a delay to see its effect on the waveform.")],
 [("Why does a testbench have no ports?", ["It is the outermost module that surrounds the design", "Ports are not allowed in simulation", "It has only outputs", "It is synthesised"], 0, "It generates inputs and watches outputs itself."),
  ("How do you make a clock with a period of 10?", ["always #5 clk = ~clk;", "always #10 clk = 1;", "initial clk = 10;", "assign clk = 10;"], 0, "Toggle every half period."),
  ("Why use !== instead of != in a check?", ["so that x and z are caught as mismatches", "it is faster", "it is required by Verilog", "it works on wires only"], 0, "It never returns x."),
  ("What makes a testbench self-checking?", ["it compares outputs to expected values and reports pass or fail", "it has a clock", "it uses dollar-display", "it is short"], 0, "No human needs to inspect it."),
  ("Which input values find boundary bugs best?", ["equal values, zero and maximum", "only typical values", "random only", "none"], 0, "Bugs often hide at the edges.")],
 [("Testbench shape", "no ports; reg inputs, wire outputs, DUT, initial"), ("Clock", "always #5 clk = ~clk;"), ("Check", "if (out !== expected) errors"), ("Rule", "a test must be able to fail")],
 [MATCH("Testbench parts", "Match each part to its job.", [("reg", "drives the DUT's inputs"), ("wire", "carries the DUT's outputs"), ("initial", "runs the test once"), ("always #5 clk = ~clk", "generates the clock")]),
  FILL("Checking", "A testbench has {{no}} ports. It drives inputs declared as {{reg}} and watches outputs declared as {{wire}}. To catch x values use the {{!==}} operator. A reference model gives the {{expected}} answer."),
  ORDER("A self-checking test", "Put the steps in order.", ["apply inputs", "wait for the logic to settle", "compare outputs to the reference", "count errors and print the result"])]))

CHS.append(CH(
 "Finite state machines: designing circuits that follow a plan",
 ("State machines", []),
 ["A finite state machine, or FSM, is a circuit that is always in one of a small number of states, and moves between them depending on its inputs. Traffic lights, vending machines, protocol controllers and sequence detectors are all FSMs.",
  "Every FSM has the same three parts: a state register, next-state logic and output logic. The Moore style makes outputs depend only on the state; the Mealy style also uses the inputs.",
  "This chapter gives a method: draw the diagram, choose state names, then write the three parts in Verilog."],
 [("State", "A situation the machine can be in, remembered by flip-flops."),
  ("Transition", "A move from one state to another, taken at a clock edge depending on inputs."),
  ("Moore machine", "Outputs depend only on the current state."),
  ("Mealy machine", "Outputs depend on the current state and the current inputs."),
  ("State encoding", "How states are written in bits: binary, one-hot, and so on."),
  ("localparam", "A constant local to a module, used to name states."),
  ("Next-state logic", "The combinational logic that decides which state comes next.")],
 ["An FSM has a state register, next-state logic and output logic.",
  "Moore: output = f(state). Mealy: output = f(state, input).",
  "Name the states with localparam and use a case on the state.",
  "Write the state register in a clocked always block with <=, and the next-state and output logic in combinational blocks.",
  "Always reset the FSM to a known initial state."],
 [T("Think of a turnstile at a station. It has two situations: locked and unlocked. Drop a coin while it is locked and it unlocks. Push while it is unlocked and it locks again. These situations are called states. The coin and the push are inputs. The rule that says what state comes next is the transition. That is a complete state machine, drawn on the back of a napkin."),
  T("Any FSM, however big, is made of three pieces. A register of flip-flops remembers the current state. Next-state logic looks at the current state and the inputs and decides which state comes next. Output logic decides what the outputs are. The register is clocked, the other two are combinational, and the state loops back to the next-state logic. (See Figure 12.1 below.)"),
  F("vl-fsmstruct.svg", "The three parts of every FSM. The dashed arrow is the extra path that makes a machine a Mealy machine."),
  T("There are two flavours of output. In a Moore machine, outputs depend only on the state: a traffic light shows red because it is in the red state. In a Mealy machine, outputs may also depend on the inputs right now, so they can react a clock cycle earlier and often need fewer states. Mealy outputs can also change when an input changes between clock edges, which makes them more sensitive to glitches. (See Table 12.1 below.)"),
  TB("Moore versus Mealy", ["", "Moore", "Mealy"], [["output depends on", "state only", "state and inputs"], ["output changes", "only at clock edges", "also when inputs change"], ["number of states", "often more", "often fewer"], ["reaction time", "one cycle later", "same cycle"], ["example", "traffic light", "sequence detector"]]),
  T("Here is the recipe. First, list the states and name them. Second, draw the diagram: a circle for each state, an arrow for each transition, labelled with the input that causes it (and the output, for Mealy). Third, check every state has an arrow for every possible input. Fourth, write the Verilog: names with localparam, state register, next-state case, outputs."),
  T("The first example is a traffic light with three states in a loop: red, then green, then yellow, then red again. The outputs are simply which light is on. Because the outputs depend only on the state, it is a Moore machine. In Verilog the next-state logic is a case statement, and each output is an assign comparing the state with a name. (See Figure 12.2 below.)"),
  F("vl-traffic.svg", "A Moore traffic light. The outputs are decoded from the state."),
  V("module traffic(input clk, input rst, output red, output green, output yellow);\n  localparam RED = 2'd0, GREEN = 2'd1, YELLOW = 2'd2;\n  reg [1:0] state, next;\n\n  always @(posedge clk)             // state register\n    if (rst) state <= RED; else state <= next;\n\n  always @* begin                    // next-state logic\n    case (state)\n      RED:     next = GREEN;\n      GREEN:   next = YELLOW;\n      default: next = RED;\n    endcase\n  end\n\n  assign red    = (state == RED);    // output logic\n  assign green  = (state == GREEN);\n  assign yellow = (state == YELLOW);\nendmodule"),
  T("Look at the three parts in the code. The first block is the state register: a clocked block with a synchronous reset that goes to a known state. The second is a combinational block, with a case on the state; every branch assigns next, and the default branch covers unused codes. The last three lines are the output logic."),
  T("The second example is a sequence detector: it watches a stream of bits, one per clock, and raises an output when it has just seen the pattern 1, 0, 1. It needs to remember how much of the pattern it has matched so far. S0 means nothing matched, S1 means a 1 has been seen, S2 means 1 and 0 have been seen. A 1 in S2 completes the pattern. (See Figure 12.3 below.)"),
  F("vl-fsm101.svg", "A Mealy detector for 101. Arc labels are input over output. The detection arc goes to S1 because the final 1 might begin another 101."),
  V("always @* begin\n  case (state)\n    S0: next = x ? S1 : S0;\n    S1: next = x ? S1 : S2;\n    S2: next = x ? S1 : S0;\n    default: next = S0;\n  endcase\nend\nassign y = (state == S2) && x;     // Mealy: uses the input"),
  T("Why does the detection arc go back to S1 and not S0? Because the last 1 of one 101 can be the first 1 of the next: in the stream 10101 the pattern appears twice, overlapping. Getting such cases right is the main skill in FSM design. Always ask: after the last input, what is the longest useful partial match I still have?"),
  TB("Choosing a state encoding", ["Encoding", "3 states look like", "Flip-flops", "When to use"], [["binary", "00, 01, 10", "log2 of the states", "few flip-flops, simple logic"], ["one-hot", "001, 010, 100", "one per state", "fast, FPGA-friendly, easy to debug"], ["gray", "00, 01, 11", "log2 of the states", "only one bit changes per step"]]),
  TB("Pitfalls", ["Pitfall", "Cure"], [["forgetting to assign next in a branch", "give next a default at the top: next = state;"], ["no reset", "reset to a named initial state"], ["unused state codes", "add default: next = S0"], ["outputs from a Mealy block glitching", "register the outputs if glitches matter"], ["writing everything in one big block", "keep three separate parts"]]),
  T("The vending machine in the lab shows how the same method scales. It remembers the credit in three states: nothing, five, ten. Coins arrive as a five or a ten. When the credit reaches fifteen, a dispense signal goes high and the machine returns to the start. All the thinking is in the diagram; the Verilog then follows it line by line."),
  T("In the lab you complete four machines: a toggle button, the traffic light, the 101 detector and the vending machine. For each one the state register is given or easy, and your job is the next-state logic and the outputs. Draw the diagram on paper first. It really helps.")],
 [("What does a Moore machine's output depend on?", ["only the current state", "state and inputs", "only inputs", "only the clock"], 0, "A traffic light shows its state."),
  ("Which three parts does every FSM have?", ["state register, next-state logic, output logic", "clock, reset, enable", "ALU, memory, pc", "mux, decoder, encoder"], 0, "Register, then two combinational blocks."),
  ("Why name states with localparam?", ["to make the code readable and safe", "to save flip-flops", "it is required", "to make it faster"], 0, "Names beat bare numbers."),
  ("In the 101 detector, why does the detecting arc go to S1?", ["the last 1 may start the next 101", "it is a mistake", "to reset the machine", "to save states"], 0, "Overlapping patterns."),
  ("Which encoding uses one flip-flop per state?", ["one-hot", "binary", "gray", "none"], 0, "Only one bit is high.")],
 [("Three parts", "State register, next-state logic, output logic"), ("Moore / Mealy", "Output from state / from state and input"), ("Recipe", "States, diagram, check every input, then code"), ("Safety", "Reset, default next, default case")],
 [MATCH("FSM words", "Match each to its meaning.", [("state register", "remembers where we are"), ("next-state logic", "decides where to go"), ("Moore output", "depends only on state"), ("Mealy output", "also depends on the input")]),
  FILL("State machines", "In a {{Moore}} machine the output depends only on the state. A {{Mealy}} machine also uses the inputs. The current state is held in a {{register}} that is updated at the clock edge. States are named with {{localparam}}."),
  ORDER("Designing an FSM", "Order the steps.", ["List and name the states", "Draw the diagram with every transition", "Write the state register and next-state case", "Write the output logic and test it"])]))

CHS.append(CH(
 "Building big: hierarchy, parameters, generate, functions and memories",
 ("Reuse and structure", []),
 ["A real design has hundreds of modules, many of them variations of the same thing. Verilog has tools for reuse: parameters to change widths, generate loops to repeat structures, functions to share calculations, and arrays for memories.",
  "This chapter shows how to turn a fixed 8-bit register into a register of any width, build an N-bit adder from a loop, write a function, and describe a ROM and a RAM.",
  "These tools let you write a design once and use it many times."],
 [("Parameter", "A constant of a module that can be overridden when the module is instantiated."),
  ("Generate", "Compile-time repetition of hardware using a genvar loop."),
  ("genvar", "A loop variable that exists only at compile time, for generate loops."),
  ("Function", "A reusable combinational calculation that returns one value."),
  ("Task", "A reusable block of procedural code; mostly used in testbenches."),
  ("Memory", "An array of registers: reg [7:0] mem [0:15] is 16 words of 8 bits."),
  ("`define / `include", "Text macros and file inclusion handled before compilation.")],
 ["module m #(parameter N = 8)(...) makes the width a knob; instantiate with m #(.N(12)).",
  "generate for (genvar) repeats hardware at compile time.",
  "A function returns a value computed from its inputs, with no delays.",
  "A memory is an array: reg [7:0] mem [0:15]; read it with mem[addr].",
  "Write once, reuse many times: that is the aim of every feature here."],
 [T("Suppose you wrote an 8-bit register last week, and today you need a 12-bit one and a 3-bit one. Copying and editing the file three times is a recipe for bugs. Verilog's answer is parameters. A parameter is a constant declared in the module header, with a default value, that the instantiating module can override. (See Figure 13.1 below.)"),
  V("module reg_n #(parameter N = 8)(input clk, input [N-1:0] d, output reg [N-1:0] q);\n  always @(posedge clk) q <= d;\nendmodule\n\n// in another module:\nreg_n #(.N(12)) u12(.clk(clk), .d(d12), .q(q12));\nreg_n #(.N(3))  u3 (.clk(clk), .d(d3),  .q(q3));"),
  F("vl-param.svg", "One parameterised module used twice, at widths 12 and 3."),
  T("The widths in the port list are written in terms of N. When an instance says #(.N(12)), the whole module is created with N equal to 12. If the instance says nothing, the default of 8 applies. This is how libraries of adders, FIFOs and counters are written: one source, any size."),
  TB("Parameters and friends", ["Item", "Meaning", "Changeable?"], [["parameter", "module constant with a default", "yes, at instantiation with #(.N(...))"], ["localparam", "module constant that cannot be overridden", "no; good for state names"], ["`define", "text replacement macro, global to the file", "by redefining before use"], ["integer / genvar", "loop counters", "not hardware"]]),
  T("Sometimes a parameter changes not just a width but the amount of hardware. An N-bit ripple adder has N full adders. You could write them by hand, but with a generate loop you write one and ask for N copies. The loop runs while the design is being built, not while it runs: a genvar is a compile-time counter, and each iteration places another instance of the hardware."),
  V("module addn #(parameter N = 6)(input [N-1:0] a, input [N-1:0] b, input cin, output [N-1:0] sum, output cout);\n  wire [N:0] c;\n  assign c[0] = cin;\n  genvar i;\n  generate\n    for (i = 0; i < N; i = i + 1) begin : fa\n      full_adder f(.a(a[i]), .b(b[i]), .cin(c[i]), .sum(sum[i]), .cout(c[i+1]));\n    end\n  endgenerate\n  assign cout = c[N];\nendmodule"),
  T("Each iteration of the generate loop creates a block named fa, with an instance inside it, so the copies are called fa[0].f, fa[1].f and so on. The carry wires c[i] and c[i+1] join each copy to its neighbour. Change N to 32 and you get a 32-bit ripple adder, with no other change."),
  T("Next, functions. A function computes a value from its inputs and returns it: no delays, no clocks. It is ideal for a calculation used in several places, such as converting binary to Gray code. Inside the function you assign the result to the function's own name. A function can be called anywhere an expression is allowed. Tasks are similar but may contain delays and several outputs, and are mostly used in testbenches."),
  V("function [3:0] to_gray;\n  input [3:0] x;\n  begin\n    to_gray = x ^ (x >> 1);\n  end\nendfunction\n\nassign g = to_gray(b);"),
  TB("Function or task?", ["", "function", "task"], [["returns", "one value", "none, or several outputs"], ["may contain delays?", "no", "yes"], ["called from", "inside an expression", "as a statement"], ["typical use", "calculations in the design", "stimulus and checking in testbenches"]]),
  T("Now memories. A memory in Verilog is just an array of registers. The declaration reg [7:0] mem [0:15]; makes 16 words of 8 bits each. You index it with an address: mem[5] is one word. A ROM, a read-only memory, is filled once, often in an initial block, and read with an assign. A RAM can also be written: on a clock edge, if the write enable is high, the addressed word takes the input data. (See Figure 13.2 below.)"),
  F("vl-memory.svg", "A 16 by 8 memory. The address selects one word; a clocked write happens when we is 1."),
  V("module ram16(input clk, input we, input [3:0] addr, input [7:0] din, output [7:0] dout);\n  reg [7:0] mem [0:15];\n  always @(posedge clk)\n    if (we) mem[addr] <= din;\n  assign dout = mem[addr];\nendmodule"),
  T("This RAM has a clocked write and an immediate, combinational read. Real FPGA block memories often have a clocked read, and the tools are happy with either as long as you follow their coding style. Synthesis maps arrays like this to the dedicated memory blocks in an FPGA, or to a memory generator in an ASIC, so you do not build them from individual flip-flops."),
  TB("Memory kinds in Verilog", ["Kind", "Write", "Read", "Typical declaration"], [["ROM", "once, at start (initial or file)", "assign dout = mem[addr];", "reg [7:0] mem [0:15];"], ["RAM, async read", "clocked, with write enable", "assign dout = mem[addr];", "reg [7:0] mem [0:15];"], ["RAM, sync read", "clocked", "inside the clocked block", "reg [7:0] mem [0:15];"], ["register file", "clocked, 1 or 2 ports", "two read addresses", "reg [31:0] r [0:31];"]]),
  T("Two last conveniences. The define macro replaces a name by text everywhere it is used, for example a fixed bus width. The include directive pastes another file in at that point, which is handy for shared constants. Both are handled before the compiler sees the code, by the preprocessor, and they are the first stage in the toolchain you will run in the labs."),
  T("In the lab you build a register of any width, an N-bit adder with a generate loop, a Gray-code function, a ROM of squares and a RAM. The ROM level uses an initial block with a for loop to fill the array; that is the simplest way to create contents without an external file.")],
 [("How do you override a parameter N when instantiating a module?", ["reg_n #(.N(12)) u1(...);", "reg_n u1(N = 12);", "defparam only", "you cannot"], 0, "Use the #(...) list."),
  ("What is a genvar?", ["a loop counter used at compile time in generate loops", "a gate variable", "a wire", "a register"], 0, "It only exists while the design is built."),
  ("What does reg [7:0] mem [0:15]; declare?", ["16 words of 8 bits", "8 words of 16 bits", "a 128-bit register", "a single byte"], 0, "Word width goes before the name, depth after."),
  ("A function in Verilog...", ["returns one value, with no delays", "runs on the clock", "has no inputs", "must be in a testbench"], 0, "It is a combinational calculation."),
  ("Which keyword cannot be overridden at instantiation?", ["localparam", "parameter", "both", "neither"], 0, "localparam is fixed inside the module.")],
 [("Parameter", "module m #(parameter N = 8)(...)"), ("Generate", "genvar i; generate for (...) begin ... end endgenerate"), ("Memory", "reg [7:0] mem [0:15];"), ("Function", "assign the result to the function's name")],
 [MATCH("Reuse tools", "Match each tool to its job.", [("parameter", "change a width at instantiation"), ("generate for", "repeat hardware N times"), ("function", "reusable calculation"), ("reg [7:0] mem [0:15]", "a 16-word memory")]),
  FILL("Memories", "A memory is an {{array}} of registers. reg [7:0] mem [0:15] has {{16}} words of {{8}} bits. A RAM write needs a clock edge and a write {{enable}}."),
  ORDER("Making an N-bit adder", "Order the steps.", ["Add a parameter N", "Declare a carry vector of N+1 bits", "Use a generate loop to place N full adders", "Connect the last carry to cout"])]))

CHS.append(CH(
 "From RTL to silicon, and a tiny CPU to prove it",
 ("RTL to chip", []),
 ["You can now describe hardware. This last chapter shows where it goes: which Verilog the tools can turn into gates, how an FPGA or an ASIC is made from it, and how timing is checked.",
  "Then we use everything you have learnt to build a complete 8-bit processor, one block at a time: ALU, program counter, control decoder and top level. You finish by writing a program for the CPU you made.",
  "This is the point of the whole course: an idea described in a few dozen lines, simulated, and ready to become silicon."],
 [("Synthesis", "Turning RTL into a netlist of gates and flip-flops from a library."),
  ("Synthesisable subset", "The part of Verilog that tools can turn into hardware."),
  ("Static timing analysis", "Checking that every path meets its clock period without simulating."),
  ("Bitstream", "The configuration data loaded into an FPGA."),
  ("GDSII", "The layout file sent to a chip factory."),
  ("ISA", "Instruction set architecture: the instructions a processor understands."),
  ("Datapath / control", "The parts that hold and transform data, and the part that tells them what to do.")],
 ["Synthesis turns RTL into a gate netlist; FPGA and ASIC flows then place and route it.",
  "Write synthesisable RTL: clocked always blocks with <=, combinational with =, no delays, fixed loops.",
  "Static timing analysis checks every path against the clock period.",
  "A CPU is a datapath (registers, ALU) plus control that decodes instructions.",
  "Fetch, decode, execute, write back: one instruction per clock in our tiny CPU."],
 [T("Your simulation passes. What now? The design goes through synthesis. A synthesis tool reads your Verilog, works out what hardware you meant, and maps it onto the gates and flip-flops of a target library. The result is a netlist: a long list of gates and the wires between them. You also give it constraints, such as the clock speed you want and the pins to use. (See Figure 14.1 below.)"),
  F("vl-synth.svg", "After synthesis the flow splits. An FPGA flow places the netlist into programmable logic and produces a bitstream. An ASIC flow produces a full layout."),
  T("For an FPGA, the next steps are place and route: assign each gate to a lookup table somewhere on the chip and connect them through the programmable wiring. The tool outputs a bitstream, which you load into the chip. For an ASIC, the steps are longer: floorplanning, placement, clock tree building, routing, and a long list of checks, ending in the layout file sent to the factory."),
  TB("FPGA flow versus ASIC flow", ["Step", "FPGA", "ASIC"], [["synthesis", "to lookup tables and flip-flops", "to a standard cell library"], ["placement and routing", "into existing programmable fabric", "into a custom floorplan"], ["checks", "timing and pin constraints", "timing, power, design rules, layout versus schematic"], ["result", "bitstream, loaded in seconds", "GDSII file, then weeks in a factory"], ["fix a bug", "reprogram", "new masks: very expensive"]]),
  T("Not all Verilog can be synthesised. Delays like #5 are ignored. Initial blocks mostly are not hardware, apart from setting FPGA starting values. Loops need a fixed count. Dividing by a variable is huge. The safe subset is: assign statements, combinational always @* blocks with blocking assignment, clocked always blocks with non-blocking assignment, parameters, generate loops and instances. This course used this subset in every design lab."),
  TB("What synthesis understands", ["Construct", "Becomes", "Careful"], [["assign, always @*", "logic gates", "assign every output on every path"], ["always @(posedge clk)", "flip-flops", "give a reset"], ["case, if / else", "multiplexers and priority logic", "add default and else"], ["for with fixed bounds", "unrolled logic", "bounds must be constants"], ["# delays, initial for simulation", "ignored", "do not depend on them"]]),
  T("How does the tool know your design is fast enough? Static timing analysis. It does not simulate. It adds up the delays along every path from one flip-flop to the next using the library numbers, and compares each sum to the clock period. A path with negative slack fails. The report lists the worst paths, which are your critical paths, and tells you where to improve the design."),
  T("Now the best part. Let us build something real: an 8-bit accumulator CPU. It has one 8-bit register, the accumulator, and a small ROM holding the program. Each instruction is eight bits: the upper four bits are the opcode and the lower four bits are an operand. There are seven instructions: load immediate, add, subtract, and, jump if not zero, output, and halt. (See Figure 14.2 below.)"),
  F("vl-isa.svg", "The instruction format and the seven instructions of the tiny CPU."),
  TB("The tiny CPU's instructions", ["Hex", "Name", "Effect"], [["0n", "LDI n", "acc = n"], ["1n", "ADD n", "acc = acc + n"], ["2n", "SUB n", "acc = acc - n"], ["3n", "AND n", "acc = acc AND n"], ["4a", "JNZ a", "if acc is not 0, pc = a"], ["50", "OUT", "out = acc"], ["60", "HALT", "stop"]]),
  T("The CPU is a datapath plus a controller. The datapath holds the data: the program counter pc, the instruction ROM, the accumulator and the ALU. The controller is a decoder that looks at the opcode and sets the control signals: whether to load an immediate, which ALU operation to use, whether to jump, whether to output, whether to halt. (See Figure 14.3 below.)"),
  F("vl-cpu.svg", "The tiny CPU. The program counter fetches from the ROM; the control decodes; the ALU computes; the accumulator stores."),
  T("Every clock cycle does one instruction. The pc supplies an address to the ROM, which gives back an instruction. The control block decodes it. If it is an ALU instruction, the ALU combines the accumulator and the operand, and the result is written back to the accumulator at the clock edge. The pc then adds one, or jumps to the operand if a JNZ finds the accumulator not zero. HALT stops the pc."),
  V("// the heart of the top level\nalways @(posedge clk) begin\n  if (rst) begin acc <= 8'd0; out <= 8'd0; end\n  else begin\n    if (ld_imm)  acc <= {4'b0000, instr[3:0]};\n    if (use_alu) acc <= alu_y;\n    if (out_en)  out <= acc;\n  end\nend"),
  T("The lab builds this CPU in five steps, each checked by its own testbench. First the ALU: a case statement. Second the program counter: a register with reset, enable and load. Third the control decoder: a case on the opcode. Fourth the top level, wiring all of them together, running a program that adds 3, 4 and 5 to show 12. Fifth, you write your own program."),
  T("The last level is the best. You become the programmer. The ROM is the only thing you change, and you write the machine code by hand: 04, 50, 21, 41, 60. That is a loop that counts down from 4 and prints each value. When your waveform shows 4, 3, 2, 1, you have designed hardware, tested it, and programmed it, with nothing but what this course taught you."),
  TB("Where to go next", ["Topic", "What it adds"], [["SystemVerilog", "a modern superset: logic type, always_ff, interfaces, assertions"], ["Verification methods", "random constraints, coverage, UVM"], ["Formal verification", "proving properties instead of testing"], ["FPGA boards", "run your designs on real hardware"], ["Open-source flows", "Yosys, OpenROAD and open PDKs: from Verilog to GDSII for free"], ["VHDL", "the other main language; the same ideas in a different syntax"]]),
  T("A last word. The labs in this course run the Icarus Verilog compiler, compiled to WebAssembly by the VeriSim project, entirely inside your device. You can take any module from the course, paste it into a desktop copy of Icarus Verilog or an FPGA tool, and it will run. Hardware design is a craft of habits: draw first, name things, simulate everything, keep it simple. Good luck.")],
 [("What does synthesis produce?", ["a netlist of gates and flip-flops", "a waveform", "a testbench", "a schematic only"], 0, "It maps RTL onto a library."),
  ("Which Verilog is ignored by synthesis?", ["# delays", "assign", "always @(posedge clk)", "instances"], 0, "Delays only matter in simulation."),
  ("What does static timing analysis do?", ["adds up path delays and compares them with the clock period", "simulates every input", "draws the layout", "writes the testbench"], 0, "It needs no stimulus."),
  ("In the tiny CPU, which instruction stops the pc?", ["HALT", "JNZ", "OUT", "SUB"], 0, "halt disables the pc."),
  ("The opcode of the tiny CPU is in...", ["instruction bits [7:4]", "bits [3:0]", "the ROM address", "the accumulator"], 0, "The operand is in [3:0].")],
 [("Flow", "RTL, synthesis, place and route, timing, layout or bitstream"), ("Synthesisable style", "clocked <=, combinational =, no delays, fixed loops"), ("Tiny CPU", "pc, rom, control, alu, acc; one instruction per clock"), ("Instruction", "[7:4] opcode, [3:0] operand")],
 [MATCH("The tiny CPU", "Match each block to its job.", [("pc", "holds the address of the next instruction"), ("rom", "stores the program"), ("control", "decodes the opcode into signals"), ("alu", "adds, subtracts and combines")]),
  FILL("To silicon", "A tool that turns RTL into gates is called {{synthesis}}. Checking every path against the clock period without simulating is {{static}} timing analysis. An FPGA is configured by loading a {{bitstream}}. A processor is a {{datapath}} plus a controller."),
  ORDER("One instruction", "Order what the CPU does for each instruction.", ["pc addresses the ROM", "the control decodes the opcode", "the ALU or immediate produces a result", "the accumulator updates and the pc moves on"])]))
